    +'<button class="c-btn fd-tab'+(tab==="top"?" fd-on":"")+'" data-tab="top">TOP</button>'
    +'<button class="c-btn fd-tab'+(tab==="boost"?" fd-on":"")+'" data-tab="boost">BOOST</button>'
